const e=[{id:"all",label:"All",labelHi:"सभी",emoji:"🕉️"},{id:"krishna",label:"Krishna",labelHi:"कृष्ण",emoji:"🦚"},{id:"ram",label:"Ram",labelHi:"राम",emoji:"🏹"},{id:"shiv",label:"Shiv",labelHi:"शिव",emoji:"🔱"},{id:"hanuman",label:"Hanuman",labelHi:"हनुमान",emoji:"🐒"},{id:"devi",label:"Devi/Mata",labelHi:"देवी/माता",emoji:"🌸"},{id:"ganesh",label:"Ganesh",labelHi:"गणेश",emoji:"🐘"},{id:"satsang",label:"Satsang",labelHi:"सत्संग",emoji:"🙏"}],i=[{id:"k1",titleHi:"अच्युतम केशवं कृष्ण दामोदरं",titleEn:"Achyutam Keshavam Krishna Damodaram",category:"krishna",artist:"Anuradha Paudwal",isFeatured:!1,lyricsHi:`अच्युतम केशवं कृष्ण दामोदरं
राम नारायणं जानकी वल्लभम्
कमलानयनं योगीश्वरं भक्तप्रियम्
श्री मधुसूदनं भक्त कल्पद्रुमम्

जलज नयनं, सर्वभूत हृदालयम्
गोपिका रंजनं प्रेम पूर्ण हृदम्
आनन्दकंदम् अतुलित तेजसम्
गोकुल नंदनम् विश्व वंदितम्`,transliteration:`Achyutam Keshavam Krishna Damodaram
Rama Narayanam Janaki Vallabham
Kamalanayanam Yogishwaram Bhaktapriyam
Shri Madhusudanam Bhakta Kalpadrumam

Jalaja Nayanam Sarvabhuta Hridalayam
Gopika Ranjanam Prema Purna Hridam
Anandakamdam Atulita Tejasam
Gokula Nandanam Vishwa Vanditam`,lyricsEn:`Achyuta (infallible), Keshava (long-haired one), Krishna the rope-bound (Damodara),
Ram, Narayana, beloved of Janaki (Sita),
Lotus-eyed one, Lord of Yogis, lover of devotees,
Shri Madhusudana (killer of demon Madhu), wish-fulfilling tree for devotees.

Lotus-eyed one, dwelling in the hearts of all beings,
The one who delights the Gopis, heart full of love,
The source of bliss, of unparalleled radiance,
The joy of Gokul, revered by the entire universe.`},{id:"k2",titleHi:"बांके बिहारी मुझको देना सहारा",titleEn:"Banke Bihari Mujhko Dena Sahara",category:"krishna",artist:"Traditional",lyricsHi:`बांके बिहारी मुझको देना सहारा
तेरी शरण में आया हूँ, तुम बिन कौन हमारा

नंदलाल गिरधर प्रभु वृंदावन के वासी
तेरे दर पर माथा टेका, हूँ जनम का दासी

मोहन मुरली वाले, बृज के बलखाते
पतित पावन नाम तेरा, जग में गाते जाते`,transliteration:`Banke Bihari Mujhko Dena Sahara
Teri Sharan Mein Aaya Hoon, Tum Bin Kaun Hamara

Nandlal Giradhar Prabhu Vrindavan Ke Vasi
Tere Dar Par Matha Teka, Hoon Janam Ka Dasi

Mohan Murli Wale, Brij Ke Balkhate
Patit Pavan Naam Tera, Jag Mein Gaate Jaate`,lyricsEn:`O Banke Bihari, please give me your support,
I have come to your shelter, who else do I have but you?

O Nandlal, Giridhar, Lord residing in Vrindavan,
I bow at your door, I am your servant since birth.

O Mohan who plays the flute, swaying in Braj,
Your name purifies the fallen; the world keeps singing it.`},{id:"k3",titleHi:"छोटी छोटी गैया छोटे छोटे ग्वाल",titleEn:"Choti Choti Gaiya Chote Chote Gwal",category:"krishna",artist:"Traditional",isFeatured:!0,lyricsHi:`छोटी छोटी गैया छोटे छोटे ग्वाल
छोटे से मेरे मदन गोपाल

लाल की लीला अद्भुत न्यारी
बृज की गलियों में फिरे मुरारी

माखन चुराते नटखट नंदलाला
गोपियाँ पकड़ें वो भागे गोपाला`,transliteration:`Choti Choti Gaiya Chote Chote Gwal
Chote Se Mere Madan Gopal

Lal Ki Leela Adbhut Nyari
Brij Ki Galiyon Mein Phire Murari

Makhan Churate Natkhat Nandlala
Gopiyan Pakden Vo Bhaage Gopala`,lyricsEn:`Small small cows, small small cowherd boys,
My little Madan Gopal (Krishna).

The Lord's divine play is wondrous and unique,
Murari (Krishna) roams the lanes of Braj.

The mischievous Nandlal steals butter,
When the Gopis try to catch him, Gopal runs away.`},{id:"k4",titleHi:"मीठी मीठी मेरे सांवरे की मुरली बाजे",titleEn:"Mithi Mithi Mere Sanware Ki Murli Baje",category:"krishna",artist:"Traditional",lyricsHi:`मीठी मीठी मेरे सांवरे की मुरली बाजे
सुन सुन मोहित होती मेरी जिया

यमुना के तट पर खड़े श्याम बाँसुरी बजाएँ
गोपियाँ सब दौड़ पड़ीं, सुन के नाद आया

राधा प्रिय माधव की अधर धरी मुरलिया
धुन में खोया जग सारा, मस्त भई दुनिया`,transliteration:`Mithi Mithi Mere Sanware Ki Murli Baje
Sun Sun Mohit Hoti Meri Jiya

Yamuna Ke Tat Par Khade Shyam Bansuri Bajaayen
Gopiyan Sab Daud Padin Sun Ke Naad Aaya

Radha Priya Madhav Ki Adhar Dhari Muraliya
Dhun Mein Khoya Jag Sara Mast Bhai Duniya`,lyricsEn:`Sweet sweet plays the flute of my dark-complexioned beloved,
Hearing it again and again, my heart is enchanted.

Shyam stands on the banks of Yamuna, playing his flute,
All the Gopis come running, drawn by the divine sound.

Radha's beloved Madhav holds the flute to his lips,
The whole world is lost in the melody, the universe is in bliss.`},{id:"k5",titleHi:"यशोदा का नंदलाला",titleEn:"Yashoda Ka Nandlala",category:"krishna",artist:"Traditional",lyricsHi:`यशोदा का नंदलाला, देवकी का दुलारा
बृज का राजदुलारा, राधा का प्यारा

मटकी फोड़ माखन खाए
नंदलाल घर घर जाए

कदम्ब तले खड़े गिरधारी
मोहन सुंदर मन से प्यारी`,transliteration:`Yashoda Ka Nandlala, Devaki Ka Dulara
Brij Ka Raj Dulara, Radha Ka Pyara

Mataki Phod Makhan Khaaye
Nandlal Ghar Ghar Jaaye

Kadamb Tale Khade Giradhari
Mohan Sundar Man Se Pyari`,lyricsEn:`Yashoda's darling Nandlal, Devaki's beloved child,
The jewel of Braj's royal family, Radha's dear one.

Breaking the pots to eat butter,
Nandlal goes from house to house.

Giridhari (Krishna) stands beneath the Kadamba tree,
Mohan (the enchanter) is beautiful and dear to the heart.`},{id:"k6",titleHi:"श्याम रंग में रंगी चुनरिया",titleEn:"Shyam Rang Mein Rangi Chunariya",category:"krishna",artist:"Traditional",lyricsHi:`श्याम रंग में रंगी चुनरिया मेरी
श्याम रंग में रंगी

प्रेम रंग से रंग गई मेरी सारी काया
कृष्ण के दरसन से जीवन हो गया माया

वृंदावन की गलियों में खोई हूँ मैं यारी
श्याम मिले तो धन्य हो जाए जीवन सारी`,transliteration:`Shyam Rang Mein Rangi Chunariya Meri
Shyam Rang Mein Rangi

Prem Rang Se Rang Gayi Meri Sari Kaya
Krishna Ke Darshan Se Jivan Ho Gaya Maya

Vrindavan Ki Galiyon Mein Khoi Hoon Main Yari
Shyam Mile To Dhanya Ho Jaaye Jivan Sari`,lyricsEn:`My veil/dupatta is dyed in Shyam's (Krishna's) color,
Dyed in the color of Shyam.

My entire being is colored with the hue of love,
By the sight of Krishna, my life has become divine.

I am lost in the lanes of Vrindavan,
If I meet Shyam, my entire life will be blessed.`},{id:"k7",titleHi:"बासो मेरे नैनन में नंदलाल",titleEn:"Baso Mere Nainan Mein Nandlal",category:"krishna",artist:"Traditional",lyricsHi:`बासो मेरे नैनन में नंदलाल
बासो मेरे नैनन में

मोर मुकुट मकराकृत कुण्डल
अधर सुधा रस पान करत हैं

नंद महर के ललन बिहारी
मेरे मन के मधुर मुरारी`,transliteration:`Baso Mere Nainan Mein Nandlal
Baso Mere Nainan Mein

Mor Mukut Makrakrit Kundal
Adhar Sudha Ras Pan Karat Hain

Nanda Mahar Ke Lalan Bihari
Mere Man Ke Madhur Murari`,lyricsEn:`O Nandlal, please reside in my eyes,
Please dwell within my eyes.

With a peacock feather crown and fish-shaped earrings,
Who drinks the nectar of ambrosia at his lips.

The cherished son of Nanda, the wanderer (Bihari),
My heart's sweet Murari (Krishna).`},{id:"k8",titleHi:"यशोमती मैया से बोले नंदलाला",titleEn:"Yashomati Maiya Se Bole Nandlala",category:"krishna",artist:"Traditional",isFeatured:!0,lyricsHi:`यशोमती मैया से बोले नंदलाला
राधा क्यों गोरी मैं क्यों काला

माता तोसे पूछत हैं ये सवाला
राधा क्यों गोरी मैं क्यों काला

दूध पीया एक ही गाय का
फिर रंग क्यों भिन्न भिन्न दिखाया

यशोदा बोली सुन मेरे लाला
राधा है गोरी तू है काला`,transliteration:`Yashomati Maiya Se Bole Nandlala
Radha Kyon Gori Main Kyon Kala

Mata Tose Puchhat Hain Ye Sawala
Radha Kyon Gori Main Kyon Kala

Doodh Piya Ek Hi Gaay Ka
Phir Rang Kyon Bhinn Bhinn Dikhaya

Yashoda Boli Sun Mere Lala
Radha Hai Gori Tu Hai Kala`,lyricsEn:`Little Nandlal asks Mother Yashomati,
Why is Radha fair and why am I dark?

He asks this question to his mother,
Why is Radha fair and why am I dark?

We both drank milk from the same cow,
Then why do we have different complexions?

Yashoda replied: Listen my dear child,
Radha is fair, and you are dark (and that is your divine beauty).`},{id:"k9",titleHi:"श्री कृष्ण गोविंद हरे मुरारी",titleEn:"Shri Krishna Govind Hare Murari",category:"krishna",artist:"Traditional",lyricsHi:`श्री कृष्ण गोविंद हरे मुरारी
हे नाथ नारायण वासुदेवाय

जय जय गोविंद जय जय माधव
जय जय गोपाल जय यदुनाथ

पार ब्रह्म परमात्मा नारायण
जगत पालक हरि नारायण`,transliteration:`Shri Krishna Govind Hare Murari
He Nath Narayan Vasudevaya

Jai Jai Govind Jai Jai Madhav
Jai Jai Gopal Jai Yadunath

Para Brahma Paramatma Narayan
Jagat Palak Hari Narayan`,lyricsEn:`O Shri Krishna, Govind, Hari (remover of sins), Murari (enemy of demon Mura),
O Lord, Narayan, son of Vasudeva.

Victory to Govind, victory to Madhav,
Victory to Gopal, victory to Yadunath (lord of the Yadus).

The Supreme Brahman, the Supreme Soul, Narayan,
The sustainer of the universe, Hari Narayan.`},{id:"k10",titleHi:"अरे द्वारपालों कन्हैया से कह दो",titleEn:"Are Dwarpalo Kanhaiya Se Keh Do",category:"krishna",artist:"Traditional",lyricsHi:`अरे द्वारपालों कन्हैया से कह दो
कोई भक्त आया है द्वार तुम्हारे

राह तकत हूँ मैं अँखियाँ बिछाए
दरस दिखा दो प्रभु एक बारे

माखन चोर नटखट नंदलाला
खोल दे अपना दिव्य द्वारा`,transliteration:`Are Dwarpalon Kanhaiya Se Keh Do
Koi Bhakt Aaya Hai Dwar Tumhare

Raah Takat Hoon Main Ankhiyan Bichhaaye
Daras Dikha Do Prabhu Ek Baare

Makhan Chor Natkhat Nandlala
Khol De Apna Divya Dwara`,lyricsEn:`O gatekeepers, please tell Kanhaiya (Krishna),
A devotee has arrived at your door.

I am waiting, with my eyes wide open (longing),
Please show me your divine sight even once, O Lord.

O butter thief, mischievous Nandlala,
Please open your divine gates.`},{id:"k11",titleHi:"राधे राधे जपो चले आएंगे बिहारी",titleEn:"Radhe Radhe Japo Chale Ayeinge Bihari",category:"krishna",artist:"Traditional",lyricsHi:`राधे राधे जपो चले आएंगे बिहारी
राधे राधे जपो चले आएंगे बिहारी

कृष्ण नाम जपते जपते मिले किशोरी
श्याम सुंदर मिले तब लगे जीवन होरी

राधे राधे जपो चाहे हो अंधेरी रात
कृष्ण करें सुबह होने की बात`,transliteration:`Radhe Radhe Japo Chale Aayenge Bihari
Radhe Radhe Japo Chale Aayenge Bihari

Krishna Naam Japat Japat Mile Kishori
Shyam Sundar Mile Tab Lage Jivan Hori

Radhe Radhe Japo Chahe Ho Andheri Raat
Krishna Karen Subah Hone Ki Baat`,lyricsEn:`Keep chanting Radhe Radhe, Bihari (Krishna) will come,
Keep chanting Radhe Radhe, Bihari will surely come.

Chanting Krishna's name repeatedly, Kishori (Radha) is found,
When Shyam Sundar (beautiful Krishna) is found, life feels like Holi.

Chant Radhe Radhe even in the darkest night,
Krishna will bring about the morning.`},{id:"k12",titleHi:"मेरे बांके बिहारी लाल",titleEn:"Mere Banke Bihari Lal Tu Itna Na Kario Shringar",category:"krishna",artist:"Traditional",lyricsHi:`मेरे बांके बिहारी लाल तू इतना न करियो श्रृंगार
देख तुझे मोहित होती राधा बारम्बार

पीताम्बर की शोभा न्यारी मोर मुकुट सोहे
मुरली की तान सुन सुन गोपियाँ मन डोले

तू दर्पण के सामने क्यों खड़ा रे बिहारी
राधे तेरे रूप की दीवानी है सारी`,transliteration:`Mere Banke Bihari Lal Tu Itna Na Kariyo Shringar
Dekh Tujhe Mohit Hoti Radha Barambar

Pitambar Ki Shobha Nyari Mor Mukut Sohe
Murli Ki Taan Sun Sun Gopiyan Man Dole

Tu Darpan Ke Saamne Kyon Khada Re Bihari
Radhe Tere Roop Ki Diwani Hai Sari`,lyricsEn:`O my Banke Bihari Lal, don't adorn yourself so much,
Seeing you, Radha is enchanted again and again.

The yellow silk garment's beauty is unique, the peacock crown looks splendid,
Hearing the tunes of the flute, the Gopis' hearts sway.

Why do you stand before the mirror, O Bihari?
Radha is completely captivated by your beauty.`},{id:"k13",titleHi:"जहाँ ले चलोगे वहीं मैं चलूँगा",titleEn:"Jahan Le Chaloge Wahin Mai Chalunga",category:"krishna",artist:"Traditional",lyricsHi:`जहाँ ले चलोगे वहीं मैं चलूँगा
मैं तेरा हूँ प्रभु तू मेरा है

तेरे बिना मेरा कहाँ ठिकाना
तू है मेरा सहारा एकमात्र

चाहे जन्म जन्म लेता रहूँ मैं
तेरी भक्ति में डूबा रहूँगा`,transliteration:`Jahan Le Chaloge Wahin Main Chalunga
Main Tera Hoon Prabhu Tu Mera Hai

Tere Bina Mera Kahan Thikana
Tu Hai Mera Sahara Ekmatra

Chahe Janma Janma Leta Rahoon Main
Teri Bhakti Mein Dooba Rahunga`,lyricsEn:`Wherever you lead me, I will follow,
I belong to you, O Lord, and you belong to me.

Without you, where is my refuge?
You alone are my support.

Even if I keep taking birth after birth,
I will remain immersed in your devotion.`},{id:"k14",titleHi:"सांवली सूरत पे मोहन दिल दीवाना हो गया",titleEn:"Sanwali Surat Pe Mohan Dil Diwana Ho Gaya",category:"krishna",artist:"Traditional",lyricsHi:`सांवली सूरत पे मोहन दिल दीवाना हो गया
कृष्ण की मुरत देख के मेरा मन मस्ताना हो गया

नीली झील में जैसे चाँद उतरे
वैसे मेरे मन में तेरा रूप ठहरे

राधे संग नाचत हैं श्याम सुंदर
नाम सुनते ही मन हो जाता मनमोहन`,transliteration:`Sanwali Surat Pe Mohan Dil Diwana Ho Gaya
Krishna Ki Murat Dekh Ke Mera Man Mastana Ho Gaya

Nili Jheel Mein Jaise Chand Utare
Vaise Mere Man Mein Tera Roop Thahare

Radhe Sang Nachhat Hain Shyam Sundar
Naam Sunate Hi Man Ho Jaata Manmohan`,lyricsEn:`My heart has gone crazy for the dark-complexioned Mohan (Krishna),
Seeing the form of Krishna, my mind has become intoxicated.

Like the moon descending into a blue lake,
Similarly your beautiful form settles in my heart.

Shyam Sundar dances with Radha,
The moment I hear the name, the mind becomes Manmohan (the mind-capturer).`},{id:"k15",titleHi:"जुग जुग जियसु ललनवा",titleEn:"Jug Jug Jiya Su Lalanwa",category:"krishna",artist:"Traditional",lyricsHi:`जुग जुग जियसु ललनवा हमारा
मोहन कन्हैया जग से न्यारा

सुंदर सलोना मनोहर बाला
सोने की लंगोट पहने नंदलाला

यशोदा रोज उठाए दुलारे
कान्हा को भोग लगाए प्यारे`,transliteration:`Jug Jug Jiyaasu Lalanwa Hamara
Mohan Kanhaiya Jag Se Nyara

Sundar Salona Manohar Bala
Sone Ki Langot Pahne Nandlala

Yashoda Roz Uthaye Dulare
Kanha Ko Bhog Lagaaye Pyare`,lyricsEn:`May our dear child live for ages and ages,
Our Mohan, Kanhaiya, who is unique in the world.

Beautiful, charming, and captivating child,
Nandlala wearing a golden loincloth.

Every morning Yashoda lovingly wakes her darling,
And offers beloved Kanha his morning meal.`},{id:"k16",titleHi:"अच्युतम केशवं भजन",titleEn:"Achyutam Keshavam Bhajan",category:"krishna",artist:"Traditional",lyricsHi:`अच्युतम केशवं कृष्ण दामोदरम्
राम नारायणम् जानकी वल्लभम्

गोविंद माधव मधुसूदन
श्री हरि विष्णु त्रिभुवन भूषण

पद्म पत्राक्षम् पुण्डरीकाक्षम्
हृत्कमलस्थम् कमलनाभम्`,transliteration:`Achyutam Keshavam Krishna Damodaram
Rama Narayanam Janaki Vallabham

Govind Madhav Madhusudana
Shri Hari Vishnu Tribhuvana Bhushana

Padma Patraksham Pundarikaksham
Hrit Kamala Stham Kamala Nabham`,lyricsEn:`The infallible Keshava, Krishna who is Damodara,
Rama, Narayana, beloved of Janaki.

Govind, Madhav, Madhusudana (killer of Madhu),
Shri Hari Vishnu, ornament of the three worlds.

With eyes like lotus petals, with lotus eyes,
Dwelling in the lotus of the heart, with a lotus navel.`},{id:"k17",titleHi:"श्री कृष्ण गोविन्द हरे मुरारी",titleEn:"Shree Krishna Govind Hare Murari",category:"krishna",artist:"Traditional",lyricsHi:`श्री कृष्ण गोविन्द हरे मुरारी
हे नाथ नारायण वासुदेव

जय जय गोविन्द जय जय माधव
जय जय गोपाल जय यदुनाथ

मुरली मनोहर श्याम सुंदर
राधा प्रिय गोकुल चंद्र`,transliteration:`Shri Krishna Govind Hare Murari
He Nath Narayan Vasudeva

Jai Jai Govind Jai Jai Madhav
Jai Jai Gopal Jai Yadunath

Murali Manohar Shyam Sundar
Radha Priya Gokula Chandra`,lyricsEn:`O Shri Krishna, Govind, Hari, Murari,
O Lord, Narayan, Vasudeva.

Victory to Govind, victory to Madhav,
Victory to Gopal, victory to Yadunath.

The flute-charmer, the beautiful dark one,
Radha's beloved, the moon of Gokul.`},{id:"r1",titleHi:"रघुपति राघव राजाराम",titleEn:"Raghupati Raghav Raja Ram",category:"ram",artist:"Traditional / Mahatma Gandhi's favorite",lyricsHi:`रघुपति राघव राजाराम
पतित पावन सीताराम
सीताराम सीताराम
भज प्यारे तू सीताराम

ईश्वर अल्लाह तेरो नाम
सब को सन्मति दे भगवान`,transliteration:`Raghupati Raghav Raja Ram
Patit Pavan Sitaram
Sitaram Sitaram
Bhaj Pyare Tu Sitaram

Ishwar Allah Tero Naam
Sab Ko Sanmati De Bhagawan`,lyricsEn:`O Raghupati (Lord of the Raghu clan), Raghav, King Ram,
Sitaram who purifies the fallen.
Sitaram Sitaram,
O dear one, worship Sitaram.

Your name is both Ishwar and Allah,
O God, grant wisdom to everyone.`},{id:"r2",titleHi:"श्री रामचन्द्र कृपालु भजमन",titleEn:"Shri Ramchandra Kripalu Bhajman",category:"ram",artist:"Tulsidas",lyricsHi:`श्री रामचन्द्र कृपालु भजमन हरण भव भय दारुणम्
नव कंज लोचन, कंज मुख कर कंज पद कंजारुणम्

कंदर्प अगणित अमित छवि नव नील नीरज सुंदरम्
पट पीत मानहुँ तड़ित रुचि शुचि नौमि जनक सुता वरम्`,transliteration:`Shri Ramchandra Kripalu Bhajaman Haran Bhav Bhay Darunam
Nav Kanj Lochan Kanj Mukh Kar Kanj Pad Kanjarunam

Kandarp Agunit Amit Chhavi Nav Nil Niraja Sundaram
Pat Pit Manahu Tadit Ruchi Shuchi Naumi Janaka Sutavaram`,lyricsEn:`Worship the merciful Shri Ramchandra, destroyer of the terrible fear of worldly existence,
With new lotus eyes, lotus face, lotus hands and lotus feet that are reddish.

More handsome than countless Kamadevas (gods of love), beautiful like a fresh blue lotus,
Wearing yellow silks that gleam like lightning, pure. I bow to the consort of Janaki (Sita).`},{id:"r3",titleHi:"जय जय राम रघुराई",titleEn:"Jay Jay Ram Raghuarai",category:"ram",artist:"Traditional",lyricsHi:`जय जय राम रघुराई
सब के मन में बसो सदाई

दशरथ नंदन सीता पति
राजा राम की जय जयती

लक्ष्मण सहित वनों में भ्रमण
भक्तों के मन में शाश्वत चरण`,transliteration:`Jai Jai Ram Raghuarai
Sab Ke Man Mein Baso Sadaai

Dashrath Nandan Sita Pati
Raja Ram Ki Jai Jayti

Lakshman Sahit Vanon Mein Bhraman
Bhakton Ke Man Mein Shashwat Charan`,lyricsEn:`Victory, victory to Ram, Lord of the Raghu clan,
May you reside forever in everyone's heart.

Son of Dasharatha, husband of Sita,
Victory to King Ram.

Roaming the forests along with Lakshmana,
Your feet are eternally present in the hearts of devotees.`},{id:"r4",titleHi:"राम सिया राम",titleEn:"Ram Siya Ram",category:"ram",artist:"Traditional",lyricsHi:`राम सिया राम, राम सिया राम
जय जय राम, जय जय राम

सीता राम की जोड़ी निराली
भक्त जन के मन हरने वाली

रघुकुल रीत सदा चली आई
प्राण जाए पर वचन न जाई`,transliteration:`Ram Siya Ram, Ram Siya Ram
Jai Jai Ram, Jai Jai Ram

Sita Ram Ki Jodi Nirali
Bhakta Jan Ke Man Harne Wali

Raghukul Reet Sada Chali Aai
Pran Jaaye Par Vachan Na Jaai`,lyricsEn:`Ram Sita Ram, Ram Sita Ram,
Victory to Ram, victory to Ram.

The pair of Sita and Ram is unique,
They captivate the hearts of all devotees.

The tradition of the Raghu clan has always continued:
Life may go, but never the promise given.`},{id:"r5",titleHi:"राम कहानी सुनो रे राम कहानी",titleEn:"Ram Kahani Suno Re Ram Kahani",category:"ram",artist:"Traditional",lyricsHi:`राम कहानी सुनो रे राम कहानी
अमर अजर अविनाशी ज्ञान की खदानी

अयोध्या के राजा दशरथ के लाला
वनवास गए पहन वल्कल माला

सीता हरण हुई रावण ने की
लंका में युद्ध की विजय हनुमान ने दी`,transliteration:`Ram Kahani Suno Re Ram Kahani
Amar Ajar Avinashi Gyan Ki Khadani

Ayodhya Ke Raja Dashrath Ke Lala
Vanvas Gaye Pahan Valkal Mala

Sita Haran Hui Ravan Ne Ki
Lanka Mein Yuddh Ki Vijay Hanuman Ne Di`,lyricsEn:`Listen to the story of Ram, listen to Ram's story,
Immortal, ageless, indestructible — a mine of wisdom.

The beloved son of King Dasharatha of Ayodhya,
He went to forest exile wearing bark garments.

Sita was abducted by Ravana,
And Hanuman brought victory in the battle of Lanka.`},{id:"r6",titleHi:"भए प्रगट कृपाला दीनदयाला",titleEn:"Bhaye Pragat Kripala Din Dayala",category:"ram",artist:"Tulsidas",lyricsHi:`भए प्रगट कृपाला दीनदयाला कौसल्या हितकारी
हर्षित महतारी मुनि मन हारी अद्भुत रूप बिचारी

लोचन अभिरामा तनु घनश्यामा निज आयुध भुज चारी
भूषन वनमाला नयन बिशाला शोभासिंधु खरारी`,transliteration:`Bhaye Pragat Kripala Dindayala Kaushalya Hitakari
Harshit Mahtari Muni Man Hari Adbhut Roop Bichari

Lochana Abhirama Tanu Ghanashyama Nij Ayudha Bhuja Chari
Bhushana Vanamala Nayana Bisala Shobha Sindhu Kharari`,lyricsEn:`The merciful, compassionate Lord appeared, the benefactor of Kaushalya,
Mother Kaushalya was overjoyed, the sages' hearts were captivated, his form was wondrous.

With charming eyes, dark-complexioned body like a rain cloud, holding weapons in four arms,
Adorned with ornaments and a garland of forest flowers, with large eyes, an ocean of beauty — the enemy of Khara (a demon).`},{id:"s1",titleHi:"महा मृत्युंजय मंत्र",titleEn:"Maha Mrityunjay Mantra",category:"shiv",artist:"Vedic",lyricsHi:`ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्
उर्वारुकमिव बन्धनान् मृत्योर्मुक्षीय मामृतात्

ॐ भूर् भुवः स्वः तत् सवितुर्वरेण्यं
भर्गो देवस्य धीमहि धियो यो नः प्रचोदयात्`,transliteration:`Om Tryambakam Yajamahe Sugandhim Pushtivardhanam
Urvarukamiva Bandhanaan Mrityor Mukshiya Maamritat

Om Bhur Bhuvah Svah Tat Savitur Varenyam
Bhargo Devasya Dhimahi Dhiyo Yo Nah Prachodayat`,lyricsEn:`We worship the three-eyed Lord Shiva who is fragrant and who nourishes all beings.
May He liberate us from death for the sake of immortality, even as the cucumber is severed from the vine.

Om (sacred sound), the physical, astral and causal worlds, we meditate on that divine radiance of the sun,
May it inspire and illuminate our intellect.`},{id:"s2",titleHi:"शिव तांडव स्तोत्रम्",titleEn:"Shiv Tandav Stotram",category:"shiv",artist:"Ravana",lyricsHi:`जटाटवीगलज्जलप्रवाहपावितस्थले
गलेऽवलम्ब्य लम्बितां भुजंगतुंगमालिकाम्
डमद्डमद्डमद्डमन्निनादवड्डमर्वयं
चकार चण्डताण्डवं तनोतु नः शिवः शिवम्

जटाकटाहसम्भ्रमभ्रमन्निलिम्पनिर्झरी
विलोलवीचिवल्लरीविराजमानमूर्धनि
धगद्धगद्धगज्जलल्ललाटपट्टपावके
किशोरचन्द्रशेखरे रतिः प्रतिक्षणं मम`,transliteration:`Jatatavigalajjalapravahapavitasthale
Gale Avalambya Lambitam Bhujangatungamalikam
Damaddamaddamaddaman Ninadavaddamarvayam
Chakara Chandatandavam Tanotu Nah Shivah Shivam

Jatakatahsambhrambhramannilimpanirjhari
Vilolavichivallarivirajamanamurdhani
Dhagaddhagaddhagajjalallalatapatapavake
Kishorachandrashekhare Ratih Pratikshanam Mama`,lyricsEn:`He whose throat is sanctified by the flowing streams from the forest of matted hair,
Who wears a garland of lofty serpents around his neck,
Who made the sky resound with the beat of Damaru drum saying Dama-Dama,
May that Shiva who performed the fierce Tandava dance grant us auspiciousness.

His hair resembles the torrent of the celestial river Ganga swirling about in agitation,
Adorning his head with flowing waves,
With fire blazing on the flat surface of his forehead,
May my love be fixed every moment on Shiva who wears the crescent moon.`},{id:"s3",titleHi:"हर हर गंगे",titleEn:"Har Har Gange",category:"shiv",artist:"Traditional",lyricsHi:`हर हर गंगे, हर हर गंगे
शिव जटा से निकली पवित्र धारा

गंगा मैया पाप हरने वाली
भव सागर से पार उतारने वाली

काशी में बसे भोलेनाथ
हर पापी का करे उद्धार`,transliteration:`Har Har Gange, Har Har Gange
Shiv Jata Se Nikli Pavitra Dhara

Ganga Maiya Paap Harne Wali
Bhav Sagar Se Par Utarne Wali

Kashi Mein Base Bholenath
Har Paapi Ka Kare Uddhaar`,lyricsEn:`Hail, hail Ganga! Hail, hail Ganga!
The sacred stream that flows from Shiva's matted locks.

Mother Ganga who washes away sins,
Who ferries one across the ocean of worldly existence.

Bholenath (Shiva) resides in Kashi (Varanasi),
Who redeems every sinner.`},{id:"s4",titleHi:"शिव शंकर को जिसने पूजा",titleEn:"Shiv Shankar Ko Jisne Pooja",category:"shiv",artist:"Hariharan",lyricsHi:`शिव शंकर को जिसने पूजा उसका बेड़ा पार हुआ
कर ले भक्ति शिव भोले की जग से न्यारा प्यार हुआ

ऊँचे पर्वत बर्फ की चादर शिव का आसन देखो
जटाओं में गंगा बहती है अद्भुत दृश्य देखो`,transliteration:`Shiv Shankar Ko Jisne Pooja Uska Beda Paar Hua
Kar Le Bhakti Shiv Bhole Ki Jag Se Nyara Pyar Hua

Unche Parvat Barf Ki Chadar Shiv Ka Aasan Dekho
Jataon Mein Ganga Bahti Hai Adbhut Drishya Dekho`,lyricsEn:`Whoever worships Shiv Shankar, their boat is ferried across (liberated),
Devote yourself to innocent Shiva, a love different from the world is found.

On the high mountains covered with snow, behold Shiva's seat,
Ganga flows through his matted locks — behold this wondrous sight.`},{id:"s5",titleHi:"मन मेरा मंदिर शिव मेरी पूजा",titleEn:"Man Mera Mandir Shiv Meri Pooja",category:"shiv",artist:"Anuradha Paudwal",lyricsHi:`मन मेरा मंदिर शिव मेरी पूजा
मन से शिव को भजूँ मैं रोज

शिव के बिना मेरा कुछ नहीं है
शिव ही मेरा जीवन है

भोले शंकर बम बम भोले
तेरे नाम से जीवन खोले`,transliteration:`Man Mera Mandir Shiv Meri Pooja
Man Se Shiv Ko Bhajoon Main Roz

Shiv Ke Bina Mera Kuch Nahin Hai
Shiv Hi Mera Jivan Hai

Bhole Shankar Bam Bam Bhole
Tere Naam Se Jivan Khhole`,lyricsEn:`My mind is the temple, Shiva is my worship,
Every day I worship Shiva with all my mind.

Without Shiva I have nothing,
Shiva alone is my life.

O innocent Shankar, Bam Bam Bhole,
Life opens up through your name.`},{id:"s6",titleHi:"हर हर महादेव",titleEn:"Har Har Mahadev",category:"shiv",artist:"Traditional",lyricsHi:`हर हर महादेव, हर हर महादेव
बोलो हर हर महादेव

भोले बाबा की जय जयकार
शिव शंकर का हो जयकार

त्रिनेत्र धारी नीलकंठ महादेव
डमरू बजाते नाचते महादेव`,transliteration:`Har Har Mahadev, Har Har Mahadev
Bolo Har Har Mahadev

Bhole Baba Ki Jai Jayakaar
Shiv Shankar Ka Ho Jayakaar

Trinetra Dhari Nilakantha Mahadev
Damru Bajate Nachte Mahadev`,lyricsEn:`Hail Hail Mahadev, Hail Hail Mahadev,
Chant Hail Hail Mahadev.

Victory to Bhole Baba,
May Shiv Shankar be victorious.

Three-eyed Nilakantha (blue-throated) Mahadev,
Mahadev who dances playing the Damaru drum.`},{id:"s7",titleHi:"भोलेनाथ की जय",titleEn:"Bholenath Ki Jay",category:"shiv",artist:"Traditional",lyricsHi:`भोलेनाथ की जय, भोलेनाथ की जय
उमापति महादेव की जय

पार्वती के प्रियतम शिव शंकर
गणेश कार्तिकेय के पिता

नंदी बैल पर सवार महेश
जग पालक जग के अधीश`,transliteration:`Bholenath Ki Jai, Bholenath Ki Jai
Umapati Mahadev Ki Jai

Parvati Ke Priyatam Shiv Shankar
Ganesh Kartikeya Ke Pita

Nandi Bail Par Savaar Mahesh
Jag Palak Jag Ke Adheesh`,lyricsEn:`Victory to Bholenath, victory to Bholenath,
Victory to Umapati (husband of Uma/Parvati) Mahadev.

Shiv Shankar, beloved of Parvati,
Father of Ganesh and Kartikeya.

Mahesh who rides the Nandi bull,
The sustainer and the lord of the world.`},{id:"s8",titleHi:"शिव स्तुति",titleEn:"Shiv Stuti — Narayan Panditacharya",category:"shiv",artist:"Narayan Panditacharya",isFeatured:!0,lyricsHi:`नमामि शम्भुं पुरुषं पुराणं
नमामि सर्वज्ञमनन्तरूपम्
नमामि रुद्रं प्रभुमप्रमेयं
नमामि शर्वं शिरसा नमामि

सदाशिव श्री गिरिजासहायम्
शम्भुं महेशं शिवमव्ययम् च
त्र्यम्बकं चंद्रधरं विशालं
नमामि दुर्गां गुरुमाद्यमव्ययम्`,transliteration:`Namami Shambhum Purusham Puranam
Namami Sarvajnamanatnarupam
Namami Rudram Prabhum Aprameya
Namami Sharvam Shirasa Namami

Sadashiva Shri Girijasahayam
Shambhum Mahesham Shivamavyayam Cha
Tryambakam Chandradharam Vishalam
Namami Durgam Gurumadyam Avyayam`,lyricsEn:`I bow to Shambhu, the eternal Purusha (cosmic being),
I bow to the omniscient one with infinite forms.
I bow to Rudra, the immeasurable Lord,
I bow to Sharva — I bow with my head.

The eternal Sadashiva, companion of Girija (Parvati),
Shambhu, Mahesh, the auspicious and indestructible.
The three-eyed one who wears the crescent moon, the expansive one,
I bow to Durga, the primordial Guru, the indestructible one.`},{id:"s9",titleHi:"सम्पूर्ण शिव अमृतवाणी",titleEn:"Sampoorna Shiv Amritwani",category:"shiv",artist:"Anuradha Paudwal",isFeatured:!0,lyricsHi:`शिव अमृत वाणी सुनो प्रेम से
भोले शंकर की महिमा अपरम्पार

जो जन शिव का भजन करे है
जन्म-जन्म के बंधन हरे है

ॐ नमः शिवाय ॐ नमः शिवाय
शिव नाम सुमर मन शिव नाम सुमर

कैलाश पर्वत पर बसे बाबा
त्रिभुवन के नाथ भोले बाबा`,transliteration:`Shiv Amrit Vani Suno Prem Se
Bhole Shankar Ki Mahima Aparampar

Jo Jan Shiv Ka Bhajan Kare Hai
Janm Janm Ke Bandhan Hare Hai

Om Namah Shivaya Om Namah Shivaya
Shiv Naam Sumar Man Shiv Naam Sumar

Kailash Parvat Par Base Baba
Tribhuvan Ke Nath Bhole Baba`,lyricsEn:`Listen to Shiva's nectar-speech with love,
The glory of innocent Shankar is boundless.

Whoever sings the bhajan of Shiva,
Their bondage of countless births is destroyed.

Om Namah Shivaya, Om Namah Shivaya,
O mind, remember Shiva's name, remember Shiva's name.

Baba (Shiva) dwells on Mount Kailash,
Bhole Baba, the lord of the three worlds.`},{id:"h1",titleHi:"हनुमान चालीसा",titleEn:"Hanuman Chalisa",category:"hanuman",artist:"Tulsidas",lyricsHi:`श्री गुरु चरण सरोज रज निज मन मुकुर सुधारि
वरनउं रघुवर विमल जसु जो दायकु फल चारि

बुद्धिहीन तनु जानिके, सुमिरौं पवन कुमार
बल बुद्धि विद्या देहु मोहि, हरहु कलेश विकार

जय हनुमान ज्ञान गुण सागर
जय कपीस तिहुं लोक उजागर

रामदूत अतुलित बल धामा
अंजनि पुत्र पवनसुत नामा`,transliteration:`Shri Guru Charan Saroj Raj Nij Man Mukur Sudhari
Varnau Raghuvar Vimal Jasu Jo Dayaku Phal Chari

Buddhihin Tanu Janike, Sumiroun Pavan Kumar
Bal Buddhi Vidya Dehu Mohi, Harahu Kalesh Vikar

Jai Hanuman Gyan Gun Sagar
Jai Kapis Tihun Lok Ujagar

Ramdoot Atalit Bal Dhama
Anjani Putra Pawanasuta Nama`,lyricsEn:`Cleansing the mirror of my mind with the dust of the lotus feet of my Guru,
I describe the pure glory of Raghuvara (Ram), which bestows the four fruits of life.

Knowing this body to be without intelligence, I remember the son of Pawan (Hanuman),
Grant me strength, intellect and wisdom, remove my miseries and imperfections.

Victory to Hanuman, ocean of wisdom and virtue,
Victory to the king of monkeys who illuminates the three worlds.

Ram's messenger, abode of immeasurable strength,
Known as Anjani's son, the son of Pawan (wind god).`},{id:"h2",titleHi:"संकटमोचन हनुमान अष्टक",titleEn:"Sankatmochan Hanuman Ashtak",category:"hanuman",artist:"Tulsidas",lyricsHi:`बाल समय रवि भक्षि लियो तब तीनहुं लोक भयो अँधियारो
ताहि सों त्रास भयो जग को यह संकट काहु सों जात न टारो
देवन आनि करी बिनती तब छाँड़ि दियो रवि कष्ट निवारो
को नहिं जानत है जग में कपि संकटमोचन नाम तिहारो

बलि चढ़त बीर हनुमान को जो कोई सच्चे मन से ध्याते
जरा मरण भव बंधन छूटें सुख संपदा घर में आते`,transliteration:`Bal Samay Ravi Bhakshi Liyo Tab Tihun Lok Bhayo Andhiyaro
Tahi Son Tras Bhayo Jag Ko Yah Sankat Kahu Son Jat Na Taro
Devan Aani Kari Binti Tab Chhandi Diyo Ravi Kasht Nivaro
Ko Nahin Janat Hai Jag Mein Kapi Sankatmochan Naam Tiharo

Bali Chadat Bir Hanuman Ko Jo Koi Sacche Man Se Dhyate
Jara Maran Bhav Bandhan Chhooten Sukh Sampada Ghar Mein Ate`,lyricsEn:`In childhood, you swallowed the sun, and all three worlds became dark,
The world was gripped with terror, no one could remove this crisis.
The gods came and pleaded, and then you released the sun, removing the suffering.
Who in the world does not know you, O monkey, by the name Sankatmochan (remover of troubles)?

Whoever meditates on brave Hanuman with a true heart,
Is freed from old age, death and worldly bondage, and prosperity comes to their home.`},{id:"h3",titleHi:"मंगल मूर्ति मारुति नंदन",titleEn:"Mangal Moorti Maruti Nandan",category:"hanuman",artist:"Traditional",lyricsHi:`मंगल मूर्ति मारुति नंदन
सकल अमंगल मूल निकंदन

पवन तनय संकट हरन
मंगल मूरत रूप

राम लखन सीता मन बसिया
जग पावन श्री दूत हनुम्या`,transliteration:`Mangal Moorti Maruti Nandan
Sakal Amangal Mool Nikandan

Pavan Tanay Sankat Haran
Mangal Moorat Roop

Ram Lakhan Sita Man Basiyan
Jag Pavan Shri Doot Hanumiyan`,lyricsEn:`Mangal Moorti (auspicious form), son of Maruti (wind god),
The root destroyer of all that is inauspicious.

Son of Pawan (wind), remover of hardships,
Auspicious form.

Ram, Lakshman and Sita reside in whose heart,
The purifier of the world, revered messenger Sri Hanuman.`},{id:"h4",titleHi:"ये बाबा तो मेरा रखवाला है",titleEn:"Ye Baba To Mera Rakhwala Hai",category:"hanuman",artist:"Traditional",lyricsHi:`ये बाबा तो मेरा रखवाला है
जब मन मेरा घबराए तो बाबा याद आए

बजरंगी बली का भक्त जब पुकारे
दौड़े आते मेरे हनुमान प्यारे

संकट में हनुमान सहायक हैं
भक्तों के रक्षक और नायक हैं`,transliteration:`Ye Baba To Mera Rakhwala Hai
Jab Man Mera Ghabraye To Baba Yaad Aaye

Bajrangi Bali Ka Bhakt Jab Pukaare
Daude Aate Mere Hanuman Pyare

Sankat Mein Hanuman Sahayak Hain
Bhakton Ke Rakshak Aur Nayak Hain`,lyricsEn:`This Baba (Hanuman) is my protector,
When my heart is anxious, Baba comes to mind.

When a devotee of the strong Bajrangi calls,
My dear Hanuman comes running.

In times of trouble, Hanuman is the helper,
He is the protector and champion of devotees.`},{id:"d1",titleHi:"आई गिरि नंदिनी — महिषासुर मर्दिनी",titleEn:"Aai Giri Nandini — Mahishasur Mardini",category:"devi",artist:"Traditional",lyricsHi:`अयि गिरिनन्दिनि नन्दितमेदिनि विश्वविनोदिनि नन्दनुते
गिरिवरविन्ध्यशिरोऽधिनिवासिनि विष्णुविलासिनि जिष्णुनुते

भगवति हे शितिकण्ठकुटुम्बिनि भूरिकुटुम्बिनि भूरिकृते
जय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते`,transliteration:`Ayi Girinandini Nanditamedini Vishvavinodini Nandanute
Girivaravindhyashiro Adhinivasini Vishnuvilasini Jishnunute

Bhagavati He Shitikanthakutumbini Bhurikutumbini Bhurikrite
Jaya Jaya He Mahishasuramardini Ramyakapardini Shailasute`,lyricsEn:`O daughter of the mountain, who delights the earth, who entertains the universe, praised by Nanda,
O you who dwells on the peaks of great mountains like Vindhya, who is loved by Vishnu, praised by Indra.

O Goddess, O consort of the blue-throated one (Shiva), of great family, of great deeds,
Victory, victory to the slayer of Mahishasura, with beautiful braided locks, daughter of the mountain.`},{id:"d2",titleHi:"सुनो शेरावाली",titleEn:"Suno Sherawali",category:"devi",artist:"Narendra Chanchal",lyricsHi:`सुनो शेरावाली सुनो शेरावाली
माँ सुनो शेरावाली

एक पुकार करे तेरे दास मिल जाएंगे
तेरे दरबार में हम सब आएंगे

माँ वैष्णो वाली का जयकार बोलो
भक्तों के द्वार माँ के खुल जाते हैं`,transliteration:`Suno Sherawali Suno Sherawali
Maa Suno Sherawali

Ek Pukar Kare Tere Das Mil Jayenge
Tere Darbar Mein Hum Sab Aayenge

Maa Vaishno Wali Ka Jayakaar Bolo
Bhakton Ke Dwar Maa Ke Khul Jaate Hain`,lyricsEn:`Listen, O Sherawali (she who rides the lion), listen O Mother,
Just one call from your servant and you will come.
We will all come to your court.

Chant the victory of Mother Vaishnodevi,
Mother's gates open for all devotees.`},{id:"d3",titleHi:"हे मां पहाड़ा वाली",titleEn:"He Maa Pahada Wali",category:"devi",artist:"Traditional",lyricsHi:`हे माँ पहाड़ा वाली, हे माँ पहाड़ा वाली
तू ही है हमारी मँझधार में माँ

तेरी महिमा अपार है माँ
तू दुनिया की आधार है माँ

नवरात्रे में पूजे सब तुझको
माँ दुर्गा तू सबकी है माँ`,transliteration:`He Maa Pahada Wali, He Maa Pahada Wali
Tu Hi Hai Hamari Manjhdar Mein Maa

Teri Mahima Apar Hai Maa
Tu Duniya Ki Aadhar Hai Maa

Navratre Mein Pooje Sab Tujhko
Maa Durga Tu Sabki Hai Maa`,lyricsEn:`O Mother of the mountains, O Mother of the mountains,
You are our support in the middle of the ocean of life, O Mother.

Your glory is boundless, O Mother,
You are the foundation of the world, O Mother.

Everyone worships you during Navratri,
O Mother Durga, you are mother of all.`},{id:"d4",titleHi:"अम्बे तू है जगदम्बे काली",titleEn:"Ambe Tu Hai Jagdambe Kaali",category:"devi",artist:"Traditional",lyricsHi:`अम्बे तू है जगदम्बे काली
जय दुर्गे जय दुर्गे खप्पर वाली

तेरे भक्त जनों पर माँ भारी
शोर मचाते कैसे रहें हमारी

जय महाकाली माँ जय भवानी
तेरी महिमा है गुण गुण ज्ञानी`,transliteration:`Ambe Tu Hai Jagdambe Kali
Jai Durge Jai Durge Khappar Wali

Tere Bhakt Janon Par Maa Bhari
Shor Machate Kaise Rahen Hamari

Jai Mahakali Maa Jai Bhavani
Teri Mahima Hai Gungun Gyani`,lyricsEn:`O Amba, you are Jagdamba (mother of the universe), Kali,
Victory to Durga, victory to Durga who holds the skull bowl.

May your grace be always upon your devotees, O Mother,
Singing your glories, how can we remain silent?

Victory to Mahakali, Mother, victory to Bhavani,
Your glory is sung and known by the wise.`},{id:"d5",titleHi:"तू मेरी माँ — हे शारदे माँ",titleEn:"Tu Meri Maa — He Sharade Maa",category:"devi",artist:"Traditional",lyricsHi:`तू मेरी माँ हे शारदे माँ
ज्ञान की दाता हे शारदे माँ

वीणावादिनी विद्यादायिनी
माँ सरस्वती शुभ फलदायिनी

हंस वाहिनी माँ शारदे
मेरे जीवन को कर उजारे`,transliteration:`Tu Meri Maa He Sharade Maa
Gyan Ki Data He Sharade Maa

Veena Vadini Vidyadayini
Maa Saraswati Shubh Phaladayini

Hans Vahini Maa Sharade
Mere Jivan Ko Kar Ujare`,lyricsEn:`You are my Mother, O Sharade (Saraswati), O Mother,
You are the giver of knowledge, O Sharade.

She who plays the veena, she who grants knowledge,
Mother Saraswati who bestows auspicious fruits.

O Mother Sharade who rides the swan,
Please illuminate my life.`},{id:"d6",titleHi:"माँ मैं खड़ा द्वारे पे",titleEn:"Maa Mai Khada Dware Pe",category:"devi",artist:"Traditional",lyricsHi:`माँ मैं खड़ा द्वारे पे
खाली न लौटाना माँ

तू ही मेरी रक्षक है
तू ही मेरी पालक है

माँ तेरे बिना मेरा क्या ठिकाना
तू ही मेरे जीवन की है माना`,transliteration:`Maa Main Khada Dware Pe
Khali Na Lautana Maa

Tu Hi Meri Rakshak Hai
Tu Hi Meri Palak Hai

Maa Tere Bina Mera Kya Thikana
Tu Hi Mere Jivan Ki Hai Mana`,lyricsEn:`Mother, I am standing at your door,
Please do not send me away empty-handed.

You alone are my protector,
You alone are my nourisher.

Without you, O Mother, where is my refuge?
You alone are the foundation of my life.`},{id:"g1",titleHi:"गणेश वंदना — सुखकर्ता दुखहर्ता",titleEn:"Ganesh Vandana — Sukhkarta Dukhaharta",category:"ganesh",artist:"Traditional (Marathi Aarti)",lyricsHi:`सुखकर्ता दुःखहर्ता वार्ता विघ्नाची
नुरवी पुरवी प्रेम कृपा जयाची

सर्वांगी सुंदर उटी शेंदुराची
कंठी झळके माळ मुक्ताफळांची

जय देव जय देव जय मंगलमूर्ती
दर्शनमात्रे मन कामना पूर्ती`,transliteration:`Sukhakarta Duhkhaharta Varta Vighnachi
Nuravi Puravi Prema Krupa Jayachi

Sarvangi Sundara Uti Shenduranchi
Kanthi Jhalake Mala Muktaphalanchi

Jai Dev Jai Dev Jai Mangalamoorti
Darshanamaatre Man Kamana Poorti`,lyricsEn:`The giver of happiness, remover of sorrow — this is the description of Vighna (obstacle-remover),
Who fulfills love and grace, removing obstacles.

Beautiful in all limbs, adorned with vermilion,
At whose neck gleams a garland of pearls.

Victory to the Lord, victory to the Lord, victory to the auspicious form,
By your mere sight, the desires of the heart are fulfilled.`},{id:"g2",titleHi:"हे शंकर सुत गौरी नंदन",titleEn:"He Shankar Sut Gauri Nandan",category:"ganesh",artist:"Traditional",lyricsHi:`हे शंकर सुत गौरी नंदन
गणपति गजानन वंदन

विद्या बुद्धि दाता गणनायक
विघ्नहर्ता गण अध्यायक

एकदंत महाकाय प्रभु
कपिलाक्ष लम्बोदर प्रभु`,transliteration:`He Shankar Sut Gauri Nandan
Ganpati Gajanan Vandan

Vidya Buddhi Data Gananayak
Vighnharta Gana Adhyayak

Ekadant Mahakay Prabhu
Kapilaksha Lambodara Prabhu`,lyricsEn:`O son of Shankar, darling of Gauri (Parvati),
I bow to Ganpati, the elephant-faced one.

The giver of knowledge and wisdom, leader of the Ganas (divine attendants),
The remover of obstacles, the head of the Ganas.

The one-tusked, large-bodied Lord,
With tawny eyes, pot-bellied Lord.`},{id:"st1",titleHi:"वैष्णव जन तो",titleEn:"Vaishnav Jan To",category:"satsang",artist:"Narsinh Mehta / Mahatma Gandhi's favorite",lyricsHi:`वैष्णव जन तो तेणे कहिए
जे पीड़ परायी जाणे रे
पर दुःखे उपकार करे तोय
मन अभिमान न आणे रे

सकळ लोक माँ सहुने वंदे
निंदा न करे केनी रे
वाच काछ मन निश्चळ राखे
धन धन जननी तेनी रे`,transliteration:`Vaishnav Jan To Tene Kahiye
Je Peed Parayi Jane Re
Par Dukhein Upakar Kare Toye
Man Abhiman Na Ane Re

Sakal Lok Maan Sahune Vande
Ninda Na Kare Keni Re
Vaach Kaachh Man Nishchal Rakhe
Dhan Dhan Janani Teni Re`,lyricsEn:`Call him a true Vaishnava (devotee of Vishnu)
Who knows and feels another's pain.
Who helps those in distress
Without pride entering his mind.

He who bows with respect to the whole world,
Criticizes no one.
Who keeps his speech, actions and mind steady —
Blessed, blessed is his mother.`},{id:"st2",titleHi:"उठ जाग मुसाफिर भोर भई",titleEn:"Uth Jag Musafir Bhor Bhai",category:"satsang",artist:"Traditional",lyricsHi:`उठ जाग मुसाफिर भोर भई
अब रैन कहाँ जो सोवत है

जब चरन धरे तो चलना है
जब जीवन मिला तो जलना है

प्रभु के दर जो जाते हैं
वो जनम-जनम के पाप मिटाते हैं`,transliteration:`Uth Jag Musafir Bhor Bhai
Ab Rain Kahan Jo Sovat Hai

Jab Charan Dhare To Chalna Hai
Jab Jivan Mila To Jalna Hai

Prabhu Ke Dar Jo Jaate Hain
Vo Janam Janam Ke Paap Mitate Hain`,lyricsEn:`Wake up, O traveler, dawn has come,
Night is gone — why are you still sleeping?

When you have feet, you must walk,
When you have life, you must shine.

Those who go to God's door,
Erase the sins of countless lifetimes.`},{id:"st3",titleHi:"मनुष्य जनम अनमोल रे",titleEn:"Manushya Janam Anmol Re",category:"satsang",artist:"Traditional",lyricsHi:`मनुष्य जनम अनमोल रे
इस जीवन को व्यर्थ न खो रे

राम नाम जपते जाओ
भव सागर से पार हो जाओ

यह जीवन क्षण भंगुर है
हरि नाम की दौलत सच्ची है`,transliteration:`Manushya Janam Anmol Re
Is Jivan Ko Vyarth Na Kho Re

Ram Naam Japte Jao
Bhav Sagar Se Paar Ho Jao

Yah Jivan Kshan Bhanghur Hai
Hari Naam Ki Daulat Sachchi Hai`,lyricsEn:`O this human birth is priceless,
Do not waste this life in vain.

Keep chanting Ram's name,
And you will cross the ocean of worldly existence.

This life is transient and momentary,
The wealth of Hari's (God's) name is the true treasure.`},{id:"st4",titleHi:"प्रभुजी तुम चंदन हम पानी",titleEn:"Prabhuji Tum Chandan Hum Pani",category:"satsang",artist:"Raidas (Ravidas)",lyricsHi:`प्रभुजी तुम चंदन हम पानी
जाकी अंग अंग बास समानी

प्रभुजी तुम घन बन हम मोरा
जैसे चितवत चंद चकोरा

प्रभुजी तुम दीपक हम बाती
जाकी जोत बरे दिन राती

प्रभुजी तुम स्वामी हम दासा
ऐसी भक्ति करे रैदासा`,transliteration:`Prabhuji Tum Chandan Hum Pani
Jaki Ang Ang Baas Samani

Prabhuji Tum Ghan Ban Hum Mora
Jaise Chitvat Chand Chakora

Prabhuji Tum Deepak Hum Batti
Jaki Jyot Bare Din Rati

Prabhuji Tum Swami Hum Dasa
Aisi Bhakti Kare Raidasa`,lyricsEn:`O Lord, you are the sandalwood and I am the water,
Your fragrance pervades every pore of my being.

O Lord, you are the dark rain cloud and I am the peacock,
Like the Chakora bird gazes at the moon.

O Lord, you are the lamp and I am the wick,
Whose flame burns day and night.

O Lord, you are the master and I am the servant,
Such is the devotion of Raidas.`},{id:"st5",titleHi:"वैष्णव जन तो तेने कहिये",titleEn:"Vaishnav Jan To Tene Kahiye",category:"satsang",artist:"Narsinh Mehta",lyricsHi:`वैष्णव जन तो तेने कहिए
जे पीड़ परायी जाणे रे
पर दुःखे उपकार करे तोय
मन अभिमान न आणे रे

लोभ शूल्यो न करे रे झूठी
माया माया न करे रे दूठी
पर स्त्री जेने माता जेहवी
जिह्वा थकी असत्य न बोले`,transliteration:`Vaishnav Jan To Tene Kahiye
Je Peed Parayi Jane Re
Par Dukhein Upakar Kare Toye
Man Abhiman Na Ane Re

Lobha Shulyoni Kare Re Jhuthi
Maya Maya Na Kare Re Duthi
Par Stri Jene Mata Jevi
Jihva Thaki Asatya Na Bole`,lyricsEn:`Call him a true Vaishnava
Who knows and feels another's pain.
Who helps those in distress
Without any pride.

Who does not covet or speak falsehood,
Who does not touch another's wealth.
Who regards another's wife as his mother,
Whose tongue speaks no untruth.`},{id:"st6",titleHi:"मन रे हरि भजी",titleEn:"Man Re Hari Bhaji — Anup Jalota",category:"satsang",artist:"Anup Jalota",lyricsHi:`मन रे हरि भजी हरि भजी
जग झूठो सब माया

हरि बिना कहाँ जाएगा
कहाँ तू धन पाएगा

इस जनम की दौलत क्षणिक
हरि नाम सत्य यही है`,transliteration:`Man Re Hari Bhaji Hari Bhaji
Jag Jhutho Sab Maya

Hari Bina Kahan Jaayega
Kahan Tu Dhan Paayega

Is Janam Ki Daulat Kshanik
Hari Naam Satya Yahi Hai`,lyricsEn:`O mind, worship Hari, worship Hari,
This world is false, all is maya (illusion).

Without Hari, where will you go?
Where will you find true wealth?

The wealth of this birth is momentary,
Hari's name alone is the truth.`},{id:"st7",titleHi:"गुरुदेव दया करके मुझको",titleEn:"Gurudev Daya Karke Mujhko",category:"satsang",artist:"Traditional",lyricsHi:`गुरुदेव दया करके मुझको अपनाओ
मेरे अंधकार को प्रकाश से भर जाओ

मैं हूँ पतित पापी बड़ा अज्ञानी
आपकी शरण में आया हूँ स्वामी ज्ञानी

गुरु बिना इस जग में कोई न हमारा
आप ही हैं मेरे जीवन का सहारा`,transliteration:`Gurudev Daya Karke Mujhko Apnao
Mere Andhakaar Ko Prakash Se Bhar Jao

Main Hoon Patit Paapi Bada Agyani
Aapki Sharan Mein Aaya Hoon Swami Gyani

Guru Bina Is Jag Mein Koi Na Hamara
Aap Hi Hain Mere Jivan Ka Sahara`,lyricsEn:`O Gurudev, by your grace, accept me as your own,
Fill my darkness with your light.

I am fallen, sinful, greatly ignorant,
I have come to your shelter, O wise Master.

Without the Guru, no one in this world is mine,
You alone are the support of my life.`},{id:"st8",titleHi:"हरि ओम तत्सत् गायन",titleEn:"Hari Om Tatsat Gayan",category:"satsang",artist:"Traditional",lyricsHi:`हरि ओम तत्सत् हरि ओम
ब्रह्म सत्य जगत मिथ्या
जीव ब्रह्म एव नापरः

ओम शांति ओम शांति ओम शांति
सर्वे भवन्तु सुखिनः
सर्वे सन्तु निरामयाः`,transliteration:`Hari Om Tatsat Hari Om
Brahma Satya Jagat Mithya
Jiva Brahma Eva Naparah

Om Shanti Om Shanti Om Shanti
Sarve Bhavantu Sukhinah
Sarve Santu Niramayah`,lyricsEn:`Hari Om — That is the truth, Hari Om,
Brahman alone is real, the world is illusion,
The individual soul is none other than Brahman.

Om Peace, Om Peace, Om Peace,
May all beings be happy,
May all beings be free from disease.`},{id:"st9",titleHi:"इतनी शक्ति हमें देना दाता",titleEn:"Itni Shakti Hamein Dena Data",category:"satsang",artist:"Traditional (Film: Ankush)",lyricsHi:`इतनी शक्ति हमें देना दाता
मन का विश्वास कमज़ोर हो न

हम चलें नेक रस्ते पे हम से
भूलकर भी कोई भूल हो न

दूर अज्ञान के हो अँधेरे
तू हमें ज्ञान की रोशनी दे

हर बुराई से बचते रहें हम
जितनी भी दे भली ज़िन्दगी दे`,transliteration:`Itni Shakti Hamein Dena Data
Man Ka Vishwas Kamzor Ho Na

Hum Chalen Nek Raste Pe Hum Se
Bhoolkar Bhi Koi Bhool Ho Na

Door Agyan Ke Ho Andhere
Tu Hamein Gyan Ki Roshni De

Har Burayi Se Bachte Rahen Hum
Jitni Bhi De Bhali Zindagi De`,lyricsEn:`Give us this much strength, O Provider,
Let not our mind's faith weaken.

We walk on the righteous path,
Let not a single mistake be made by us.

Remove the darkness of ignorance from afar,
Grant us the light of knowledge.

May we be saved from all evil,
Whatever life you give us, give us a good one.`},{id:"st10",titleHi:"चदरिया झीनी रे झीनी",titleEn:"Chadariya Jheeni Re Jheeni — Kabir",category:"satsang",artist:"Kabir Das",lyricsHi:`चदरिया झीनी रे झीनी
राम नाम रस भीनी

अष्ट कमल दल चरखा डोलै
पाँच तत्व गुण तीनी

साई तो साईं रंग रँगीजा
और जोग करे नहिं कोई

जब मोरि चादर बंद हो लागी
तब जानूँ जाए हमारी`,transliteration:`Chadariya Jheeni Re Jheeni
Ram Naam Ras Bheeni

Asht Kamal Dal Charkha Dole
Panch Tatva Gun Teeni

Sai To Sain Rang Rangija
Aur Jog Kare Nahin Koi

Jab Mori Chadar Band Ho Lagi
Tab Janoon Jaye Hamari`,lyricsEn:`This sheet (of life) is finely woven, finely woven,
Soaked in the essence of Ram's name.

The spinning wheel of eight lotus petals turns,
Five elements and three qualities (the fabric of existence).

The wise one got colored in the Master's hue,
No other practice did he need.

When my sheet is wrapped up (life ends),
Then let everyone know it is mine to go.`},{id:"st11",titleHi:"मीरा के प्रभु गिरधर नागर",titleEn:"Meera Ke Prabhu Giridhar Nagar",category:"satsang",artist:"Meerabai",lyricsHi:`मीरा के प्रभु गिरधर नागर
मिलन की आस लिए जीती हूँ

पल पल तुझको याद करती हूँ
रात दिन गुण तेरे गाती हूँ

दुनिया से मेरा कोई नाता नहीं
बस तू ही मेरा सहारा है

मीरा दासी तेरी श्याम सुंदर
तेरे दर्शन की प्यासी हूँ`,transliteration:`Meera Ke Prabhu Giridhar Nagar
Milan Ki Aas Liye Jeeti Hoon

Pal Pal Tujhako Yaad Karti Hoon
Raat Din Gun Tere Gaati Hoon

Duniya Se Mera Koi Nata Nahin
Bas Tu Hi Mera Sahara Hai

Meera Daasi Teri Shyam Sundar
Tere Darshan Ki Pyasi Hoon`,lyricsEn:`O my Lord Giridhar Nagar (Krishna who lifted the mountain),
I live with the hope of meeting you.

Every moment I remember you,
Day and night I sing your praises.

I have no relationship with the world,
You alone are my support.

Meera is your servant, O beautiful Shyam,
I am thirsty for your divine sight.`}],r=i.map(a=>({id:a.id,title:a.titleEn,deity:a.category.charAt(0).toUpperCase()+a.category.slice(1),artist:a.artist,lyricsText:a.lyricsHi,audioBase64:"",createdAt:BigInt(0)}));export{e as BHAJAN_CATEGORIES,r as MOCK_BHAJANS,i as RICH_BHAJANS};
